<div class="atlas-preview-wrap"><div class="atlas-shell"><main class="atlas-resource-main"><p class="atlas-eyebrow"><?php echo esc_html__('Personal workspace','atlas-platform');?></p><h1><?php echo esc_html__('My Atlas','atlas-platform');?></h1><section class="atlas-admin-panel"><h2><?php echo esc_html__('Saved resources','atlas-platform');?></h2><?php foreach($dashboard['saved'] as$item):?><article class="atlas-library-row"><div><h3><a href="<?php echo esc_url(add_query_arg(['page'=>'atlas-resource','id'=>$item['id']],admin_url('admin.php')));?>"><?php echo esc_html($item['title']);?></a></h3><p><?php echo esc_html($item['summary']);?></p></div><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="atlas_remove_saved_resource"><input type="hidden" name="resource_id" value="<?php echo esc_attr($item['id']);?>"><?php wp_nonce_field('atlas_remove_saved_resource');?><button class="button"><?php echo esc_html__('Remove','atlas-platform');?></button></form></article><?php endforeach;?></section><section class="atlas-admin-panel"><h2><?php echo esc_html__('Saved searches','atlas-platform');?></h2><?php foreach($dashboard['searches'] as$search):$criteria=json_decode($search['criteria_json'],true)?:[];?><p><a href="<?php echo esc_url(add_query_arg(['page'=>'atlas-resources','atlas_search'=>$criteria['query']??'','atlas_type'=>$criteria['type']??''],admin_url('admin.php')));?>"><?php echo esc_html($search['name']);?></a></p><?php endforeach;?></section></main></div></div>
